public sealed interface OrderEvent permits OrderCreatedNotification, OrderStateTransferEvent, OrderDomainEvent {
    String orderId();
}

// 1. Event Notification: Minimal payload
public record OrderCreatedNotification(String orderId, String resourceUri) implements OrderEvent {}

// 2. Event-Carried State Transfer: Full snapshot
public record OrderStateTransferEvent(String orderId, BigDecimal totalAmount, List<String> itemSkus) implements OrderEvent {}

// 3. Event Sourcing: Intent/Mutation based append-only event
public record OrderItemAddedEvent(String orderId, int sequenceNumber, String sku, BigDecimal price) implements OrderEvent {}
